from kd_common import *
i=5
Z=lambda q,a:[('z',q),('b',a)]
def mandg(): return '<ellipse rx="230" ry="40" fill="#7aa86a"/>'+g(-170,-10,1.3,tree('#2f6a3a'))+'<rect x="150" y="-30" width="30" height="24" fill="#9a8a7a"/>'
def stick(x,y,a=1): return f'<path d="M{x} {y} l{14*a} -30" stroke="#8a6a3a" stroke-width="4"/>'
def circle_dancers(n=6,r=90,cf=kodava_man):
    import math
    return ''.join(g(280+r*math.cos(2*math.pi*k/n),205+r*.3*math.sin(2*math.pi*k/n),.9,cf()) for k in range(n))
fw=foreword(i,['Every Kodava village has a sacred open green, the <b>mand</b>: no walls, no roof, just grass, a great tree and perhaps a stone. Here the village gathers at festivals; here the men dance <b>Kōlāṭ</b> with sticks and <b>Bōlakāṭ</b> with whisks and swords; here the women dance <b>Ummattāṭ</b> in a ring.',
 'This part explains the mand and the nāḍ, the rules and gatherings, and the main Kodava dances, songs and instruments, with the debate about keeping them sacred.',
 'Festivals at the mand: '+L('/kodagu/puttari/','Puttari')+', '+L('/kodagu/kailpodh/','Kailpoḷd')+'. Previous: '+L('/kodagu/igguthappa/','Igguthappa')+'. Next: '+L('/kodagu/ainmane/','The Ainmane')+'.'],Z('A temple with no building?','Yes: the mand is called an open-air temple. The sky is its roof.'))
gl=glance([('Mand','The village green, an open-air sacred ground'),('Levels','Ūr mand (village), nāḍ mand (cluster), dēva mand (temple)'),('Used for','Festival gatherings, dances, games, meetings'),('Men’s dances','Kōlāṭ, Bōlakāṭ, Kathiyāṭ, Kombāṭ, Pariyakaḷi'),('Women’s dance','Ummattāṭ'),('Other','Pīliyāṭ (peacock feathers), Vālagāṭ (to the band)'),('Drum','Duḍi, the hand-drum'),('Band','Vālaga, at weddings and festivals'),('Songs','Pāṭṭs, sung in Kodava takk'),('Puttari','Kōlāṭ for several evenings')],
 S('A village green with a great tree and men dancing with sticks',g(280,200,1,mandg())+circle_dancers(6,110),'#d8e8c8',215),Z('Who dances?','The village. Not a troupe, though troupes now perform too.'),'The village <b>green is the temple</b>.')
mand=reading('mand','THE MAND','The open-air temple',S('A large green with a tree, a stone and a path; villagers gathering',g(280,190,1.2,mandg())+''.join(g(150+k*60,215,.8,[kodava_man(),kodava_woman()][k%2]) for k in range(5)),'#d8e8c8',215),
 ['<b>Open.</b> The mand is an open ground, kept clear, often with a sacred tree and a stone.','<b>Sacred.</b> It is considered an open-air temple of the Kodavas.','<b>Gathering.</b> At Kailpoḷd and Puttari villagers gather in their local mands.','<b>Rules.</b> Before a temple festival, the village or nāḍ follows rules for some days.','<b>Owned by all.</b> The mand belongs to the community, not to a family.'],Z('Can you build on it?','No. A mand stays open.'),'Grass, a tree, <b>and the sky</b>.')
nad=reading('nad','THE NĀḌ','Villages in clusters',S('Several villages linked by paths to a central green',hills(560,100,'#7aa86a')+''.join(g(x,y,.6,ainmane(80)) for x,y in [(100,120),(460,120),(120,220),(440,220)])+g(280,180,.6,mandg())+''.join(f'<path d="M{x} {y} L280 180" stroke="#9a8a7a" stroke-width="3" stroke-dasharray="6 4"/>' for x,y in [(100,120),(460,120),(120,220),(440,220)]),'#d8e8c8',230),
 ['<b>Nāḍ.</b> Kodava villages are grouped in clusters called <b>nāḍs</b>.','<b>Three mands.</b> Accounts speak of the ūr mand of a village, the nāḍ mand of a cluster and the dēva mand linked to a temple.','<b>Order.</b> At festivals people move from one level to the next in order.','<b>Leaders.</b> Elders of leading families (takka) lead the gathering.','<b>Ūrorme.</b> The idea of village unity, <b>ūrorme</b>, is at the heart of the mand.'],Z('How big is a nāḍ?','A few villages. Big enough for a festival, small enough to know everyone.'),'Village, cluster, <b>god</b>.')
kolat=reading('kolat','KŌLĀṬ','The stick dance',S('Men in kupyas strike sticks in pairs in a ring',circle_dancers(8,140)+''.join(stick(160+k*40,170,1 if k%2 else -1) for k in range(7)),'#d8e8c8',215),
 ['<b>Sticks.</b> Men in a ring strike short sticks with partners in rhythm.','<b>Puttari.</b> Kōlāṭ is danced on several evenings after Puttari.','<b>Moves.</b> Steps change as the ring turns; pairs cross and re-cross.','<b>Martial.</b> Like most Kodava dances it is close to a martial drill.','<b>Accompaniment.</b> The duḍi and songs keep time.'],Z('Like dandiya?','Cousin of it. In Kodagu it is men’s work and a harvest duty.'),'Sticks <b>in a turning ring</b>.')
bolak=reading('bolakat','BŌLAKĀṬ','The lamp dance',S('Men dance around a tall lamp holding whisks and swords at night',g(280,210,1.4,lamp())+circle_dancers(6,120)+'<path d="M150 150 l-10 -30 M410 150 l10 -30" stroke="#f4f1ea" stroke-width="6"/>','#20243a',215),
 ['<b>Bōlak.</b> Bōlak means lamp: men dance around a lit lamp.','<b>Whisks and swords.</b> Dancers carry a yak-tail whisk (cavari) and the oḍi katti.','<b>Duḍi.</b> The dance often opens with the song “Duḍi koṭṭ Bōlakāṭ”.','<b>At weddings.</b> The free Kodava dance at weddings (Kodava āṭ) is related but not synchronised.','<b>Popular.</b> Bōlakāṭ is the best-known Kodava dance.'],Z('Swords near a lamp?','Carried, raised and turned. Never clashed in this one.'),'A ring <b>round the lamp</b>.')
umma=reading('ummattat','UMMATTĀṬ','The women’s dance',S('Women in Kodava saris dance in a ring around a brass lamp',g(280,205,1.2,lamp())+circle_dancers(7,130,kodava_woman),'#fff3cf',215),
 ['<b>Women.</b> Ummattāṭ is danced by Kodava women in traditional dress, jewellery and kumkuma.','<b>Ring.</b> They move gracefully in a circle with clapping and hand movements.','<b>For Kāverī.</b> It is commonly linked with honour to Kāverī. (Common account.)','<b>Sanctity.</b> The Karnataka Kodava Sahitya Academy suggested it should not be performed on open public stages, to keep its sanctity.','<b>Uniform.</b> The Academy also proposed a uniform pattern for the dance.'],Z('Why keep it off stage?','Because it is a prayer as much as a dance.'),'A prayer <b>in a ring</b>.')
more=cards('more','MORE DANCES','Swords, horns, shields and feathers',fig_row('A sword, deer horns, a shield and a peacock feather',[('<path d="M-30 0 l50 -8" stroke="#9a9a9a" stroke-width="6"/>',1.2),('<path d="M-10 0 l-10 -30 l-8 -6 M10 0 l10 -30 l8 -6" stroke="#8a6a3a" stroke-width="4" fill="none"/>',1.2),('<circle r="18" fill="#7a3b1f"/><circle r="6" fill="#e0a800"/>',1.2),('<path d="M0 0 q-6 -30 0 -50" stroke="#2a6a5a" stroke-width="3" fill="none"/><ellipse cy="-52" rx="7" ry="10" fill="#1d4f8a"/>',1.3),(dudi(),1)],['kathiyāṭ','kombāṭ','pariyakaḷi','pīliyāṭ','duḍi'],gy=150),
 [('⚔️','Kathiyāṭ','The knife dance, with pīcce katti and oḍi katti.'),('🦌','Kombāṭ','The horn dance, with deer horns.'),('🛡️','Pariyakaḷi','A shield-and-stick fighting display.'),('🦚','Pīliyāṭ','A dance with peacock feathers.'),('🎺','Vālagāṭ','Dancing to the vālaga band at weddings.'),('👏','Taḷipāṭ','A clapping song-dance.')],None,'Most Kodava dances <b>look like drill</b>.',intro='Names and forms vary from nāḍ to nāḍ, and several are now performed at cultural fairs.')
music=reading('music','DRUM AND BAND','Duḍi and vālaga',S('A man beats a duḍi; a band with pipes and drums plays',g(150,210,1.8,dudi())+g(110,210,1.2,kodava_man())+''.join(g(320+k*60,210,1,person('#f4f1ea')) for k in range(4))+'<path d="M330 160 l20 -20 M390 160 l20 -20" stroke="#c9a227" stroke-width="4"/>','#fff3cf',215),
 ['<b>Duḍi.</b> The hourglass-shaped hand-drum gives rhythm for songs and dances.','<b>Vālaga.</b> The vālaga, a band of pipes and drums, plays at weddings and festivals.','<b>Players.</b> Traditionally the band was played by communities such as the Meda (see '+L('/kodagu/communities/','Part 12')+').','<b>Songs.</b> Pāṭṭs carry the legends: of Kāverī, Igguthappa, ancestors and heroes.','<b>Bāḷō pāṭ.</b> Old songs sung on pilgrimage and at festivals.'],Z('Can you dance without the band?','At a wedding, nobody tries.'),'Drum, pipe, <b>song</b>.')
today=reading('today','TODAY','Keeping the dances alive',S('Children learning Kōlāṭ from an elder on a school ground',g(160,215,1.4,kodava_man())+''.join(g(270+k*50,215,.8,person(['#c0392b','#1d4f8a','#2a9d6f','#e0a800'][k]))+stick(280+k*50,190) for k in range(4)),'#d8e8c8',215),
 ['<b>Samājas.</b> Kodava Samājas hold dance and song competitions.','<b>Melas.</b> Kodava cultural melas bring dancers of all ages.','<b>Troupes.</b> Troupes perform at exhibitions and festivals outside Kodagu.','<b>Debate.</b> Elders debate which dances belong only to ritual and which may be staged.','<b>Children.</b> Many learn in school and at home before Puttari.'],Z('Are the young dancing?','Yes, and the competitions make them practise.'),'From the mand <b>to the stage</b>.')
endp=end(i,['<b>Mand.</b> The open-air village green, a sacred ground.','<b>Nāḍ.</b> Villages grouped in clusters; ūrorme, village unity.','<b>Dances.</b> Kōlāṭ, Bōlakāṭ, Ummattāṭ, Kathiyāṭ, Kombāṭ, Pariyakaḷi, Pīliyāṭ.','<b>Music.</b> Duḍi, vālaga and the pāṭṭs.'],'Part 7 is the ainmane.','The village green')
src=sources([('Mand:','Deccan Herald, “Mand: the open-air temples of Kodagu” (nāḍ, levels, rules, gatherings, stone throwing).'),('Dances:','Deccan Herald (Kodava fest: Ummathat, Kolata, Bolakat, Kathi Aat, Valagathat, Pariyakali); Coorg.com/Star of Mysore (Duḍi koṭṭ Bōlakāṭ, Talipāṭ, Kombāṭ); Kodava heritage site (Ummattāṭ, Pīliyāṭ); Kodagu First (Kodava Sahitya Academy on Ummattāṭ); Evolve Back (weapons in dances, Bōlakāṭ).')],'the link of Ummattāṭ to Kāverī is a common account; the three-level mand naming follows press accounts and may differ locally.','Dance names romanised simply.')
finish(i,'PART 6 OF 12 · MAND · KŌLĀṬ · UMMATTĀṬ',covart('Men dancing around a lamp on a village green under a great tree',g(220,190,.9,mandg())+g(220,180,1,lamp())+''.join(g(120+k*50,190,.7,kodava_man()) for k in range(5))),'The village green',
 'The <b>mand</b>, the Kodava open-air temple, and the dances danced on it: <b>Kōlāṭ</b>, <b>Bōlakāṭ</b>, <b>Ummattāṭ</b> and more, with the duḍi, the vālaga and the songs.',
 'The Kodava mand and its dances explained and illustrated: the open-air village green, nāḍ clusters, Kōlāṭ stick dance, Bōlakāṭ lamp dance, Ummattāṭ women’s dance, Kathiyāṭ, Kombāṭ, Pariyakaḷi, Pīliyāṭ, the duḍi and vālaga.',
 [fw,gl,mand,nad,kolat,bolak,umma,more,music,today,endp,src])
